// The triage agent is asked for bare JSON and reliably returns it, but a model
// can still wrap output in a fence or add a sentence. Try every shape, and fall
// back to research rather than dropping a customer's question.
const raw = String($json.response ?? '').trim();

function extractJson(text) {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  const candidate = fenced ? fenced[1].trim() : text;
  try {
    return JSON.parse(candidate);
  } catch {}
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start !== -1 && end > start) {
    try {
      return JSON.parse(candidate.slice(start, end + 1));
    } catch {}
  }
  return null;
}

const parsed = extractJson(raw) ?? {};
const allowed = ['analysis', 'advice', 'research'];
const category = allowed.includes(parsed.category) ? parsed.category : 'research';
const ctx = $('Set Customer Context').item.json;

return [{
  json: {
    category,
    routedByFallback: !allowed.includes(parsed.category),
    summary: parsed.summary ?? ctx.question,
    question: ctx.question,
    customerId: ctx.customerId,
    // Every specialist reuses this ARN, so only this run provisioned a harness.
    harnessArn: $json.harnessArn,
  },
}];

// One specialist ran, so exactly one branch reaches here. Unwrap fenced output
// and never post an empty message to Slack.
const raw = String($json.response ?? '').trim();

let text = raw;
const fenced = raw.match(/^```(?:json)?\s*([\s\S]*?)```$/);
if (fenced) text = fenced[1].trim();

if (!text) {
  text = 'The agent returned an empty response, which is usually a transient service error. Please ask again.';
}

const ctx = $('Read Triage Decision').item.json;

return [{
  json: {
    reply: text,
    answeredBy: ctx.category,
    customerId: ctx.customerId,
    usedCodeInterpreter: Array.isArray($json.toolUses)
      && $json.toolUses.some((t) => String(t?.name ?? '').includes('code_interpreter')),
    latencyMs: $json.latencyMs ?? null,
  },
}];
